package com.salespunch360.mobile.ui.account.purchase
import androidx.compose.foundation.layout.*;import androidx.compose.foundation.lazy.LazyColumn;import androidx.compose.foundation.lazy.items;import androidx.compose.material3.*;import androidx.compose.runtime.Composable;import androidx.compose.ui.Modifier;import androidx.compose.ui.text.font.FontWeight;import androidx.compose.ui.unit.dp;import androidx.lifecycle.compose.collectAsStateWithLifecycle;import androidx.lifecycle.viewmodel.compose.viewModel;import com.salespunch360.mobile.VendorPaymentViewModel;import com.salespunch360.mobile.ui.account.sales.SelectField
@Composable fun VendorPaymentScreen(padding:PaddingValues,vm:VendorPaymentViewModel=viewModel()){val s=vm.state.collectAsStateWithLifecycle().value,bills=s.bills.filter{it.branchId==s.branchId&&it.vendorId==s.vendorId};LazyColumn(Modifier.fillMaxSize().padding(padding),contentPadding=PaddingValues(16.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){item{Text("Payment-Out / Vendor Payment",style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold)};if(s.loading)item{LinearProgressIndicator(Modifier.fillMaxWidth())};s.error?.let{item{Text(it,color=MaterialTheme.colorScheme.error)}};item{SelectField("Branch",s.branchId,s.branches.map{it.id to it.name}){id->vm.update{it.copy(branchId=id,vendorId="",billId="")}}};item{SelectField("Vendor",s.vendorId,s.vendors.map{it.id to it.name}){id->vm.update{it.copy(vendorId=id,billId="")}}};item{SelectField("Purchase bill",s.billId,bills.map{it.id to "${it.number} · Outstanding ₹${it.outstanding}"}){id->val bill=bills.first{it.id==id};vm.update{it.copy(billId=id,amount=bill.outstanding)}}};item{OutlinedTextField(s.amount,{x->vm.update{it.copy(amount=x)}},label={Text("Amount")})};item{OutlinedTextField(s.date,{x->vm.update{it.copy(date=x)}},label={Text("Payment date")})};item{SelectField("Method",s.mode,listOf("CASH" to "Cash","BANK" to "Bank")){x->vm.update{it.copy(mode=x)}}};item{SelectField("Money account",s.accountId,s.accounts.filter{it.branchId==null||it.branchId==s.branchId}.map{it.id to it.name}){x->vm.update{it.copy(accountId=x)}}};item{OutlinedTextField(s.reference,{x->vm.update{it.copy(reference=x)}},label={Text("Reference")})};item{OutlinedTextField(s.notes,{x->vm.update{it.copy(notes=x)}},label={Text("Notes")})};item{Button(vm::save,enabled=!s.saving&&s.billId.isNotBlank(),modifier=Modifier.fillMaxWidth()){Text(if(s.saving)"Posting…" else "Post payment")}};item{Text("Recent payments",style=MaterialTheme.typography.titleLarge)};items(s.history,key={it.id}){ListItem(headlineContent={Text(it.number)},supportingContent={Text("${it.date} · ${it.mode}")},trailingContent={Text("₹${it.amount}")})}}}
